package com.stayhub.api.entity.analytics;

import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDateTime;

@Entity
@Table(name = "owner_financial_snapshot")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class OwnerFinancialSnapshot {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // The owner's username or user ID
    private String ownerUsername;
    
    private LocalDateTime snapshotDate;
    
    // Gross Merchandise Value (Total revenue generated by owner)
    private Double gmv;
    
    // Net Income
    private Double netIncome;
    
    // Bad debt / Unpaid bills
    private Double badDebt;
    
    // Percentage of on time payments
    private Double onTimePaymentRate;
    
    // Maintenance cost
    private Double maintenanceCost;
    
    // Service revenue (Electricity, Water, etc)
    private Double serviceRevenue;
    
    // Projected revenue for next month
    private Double projectedRevenue;
    
    // Estimated cash loss
    private Double cashLoss;
}
